drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  01 · message templates and scopes★★★ core
//  concepts: template kept as written · positional binding · minimum level · scope properties
// ─────────────────────────────────────────────────────────────────────────
//
//  The template is the grouping key; the values are properties beside it.

using static Bootcamp.Check;
using System.Globalization;
using System.Text;

// Walks the template once: {{ and }} are literal braces, {Name} or {Name:format} is a placeholder.
(List<string> Names, string Message) Render(string template, object?[] args)
{
    var names = new List<string>();
    var text = new StringBuilder();
    for (var i = 0; i < template.Length; i++)
    {
        var c = template[i];
        if ((c == '{' || c == '}') && i + 1 < template.Length && template[i + 1] == c)
        {
            text.Append(c);
            i++;
            continue;
        }
        if (c != '{')
        {
            text.Append(c);
            continue;
        }
        var end = template.IndexOf('}', i);
        if (end < 0) throw new FormatException($"unclosed placeholder in \"{template}\"");
        var hole = template[(i + 1)..end];
        var colon = hole.IndexOf(':');
        var format = colon < 0 ? null : hole[(colon + 1)..];
        var value = names.Count < args.Length ? args[names.Count] : null;
        names.Add(colon < 0 ? hole : hole[..colon]);
        text.Append(value is IFormattable f ? f.ToString(format, CultureInfo.InvariantCulture) : value?.ToString() ?? "(null)");
        i = end;
    }
    if (names.Count != args.Length)
        throw new ArgumentException($"\"{template}\" has {names.Count} placeholders but {args.Length} arguments");
    return (names, text.ToString());
}

void Log(LogContext log, Level level, string template, params object?[] args)
{
    if (level < log.Minimum) return;
    var (names, message) = Render(template, args);
    var properties = new Dictionary<string, object?>();
    foreach (var (name, value) in log.Scopes) properties[name] = value;      // outer first, so inner scopes win
    for (var i = 0; i < names.Count; i++) properties[names[i]] = args[i];    // the call's own values win over scopes
    log.Entries.Add(new LogEntry(level, template, message, properties));
}

IDisposable BeginScope(LogContext log, string name, object? value)
{
    var frame = (name, value);
    log.Scopes.Add(frame);
    return new Scope(() => log.Scopes.RemoveAt(log.Scopes.LastIndexOf(frame)));
}

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("the template is kept as written and each value becomes a named property", () =>
{
    var log = new LogContext(Level.Information);
    Log(log, Level.Information, "Order {OrderId} shipped to {Country}", 42, "NL");
    var e = log.Entries.Single();
    Eq(new object[] { e.Template, e.Message, e.Properties },
       new object[] { "Order {OrderId} shipped to {Country}", "Order 42 shipped to NL", new Dictionary<string, object?> { ["OrderId"] = 42, ["Country"] = "NL" } });
});

Test("placeholders bind to the arguments by position, whatever they are called", () =>
{
    var log = new LogContext(Level.Information);
    Log(log, Level.Warning, "Retry {Attempt} for {OrderId}", 42, 3);
    Eq(log.Entries.Single().Properties, new Dictionary<string, object?> { ["Attempt"] = 42, ["OrderId"] = 3 });
});

Test("a format applies to the message, while the property keeps the raw value", () =>
{
    var log = new LogContext(Level.Information);
    Log(log, Level.Information, "Charged {Amount:0.00} {Currency}", 12.5m, "EUR");
    var e = log.Entries.Single();
    Eq(new object[] { e.Message, e.Properties }, new object[] { "Charged 12.50 EUR", new Dictionary<string, object?> { ["Amount"] = 12.5m, ["Currency"] = "EUR" } });
});

Test("doubled braces are text, not placeholders (boundary)", () =>
{
    var log = new LogContext(Level.Information);
    Log(log, Level.Information, "Use {{id}} in the route, got {Id}", 7);
    var e = log.Entries.Single();
    Eq(new object[] { e.Template, e.Message, e.Properties }, new object[] { "Use {{id}} in the route, got {Id}", "Use {id} in the route, got 7", new Dictionary<string, object?> { ["Id"] = 7 } });
});

Test("below the minimum nothing is written, and the minimum itself is written", () =>
{
    var log = new LogContext(Level.Warning);
    Log(log, Level.Debug, "Cart {CartId} loaded", 5);
    Log(log, Level.Information, "Cart {CartId} saved", 5);
    Log(log, Level.Warning, "Cart {CartId} is slow", 5);
    Eq(log.Entries.Select(e => e.Template).ToArray(), new[] { "Cart {CartId} is slow" });
});

Test("a scope adds its property to every line inside it and stops at Dispose", () =>
{
    var log = new LogContext(Level.Information);
    using (BeginScope(log, "CorrelationId", "c-91"))
    {
        Log(log, Level.Information, "Loaded cart {CartId}", 5);
    }
    Log(log, Level.Information, "Request done");
    Eq(log.Entries.Select(e => e.Properties).ToArray(), new object[]
    {
        new Dictionary<string, object?> { ["CorrelationId"] = "c-91", ["CartId"] = 5 },
        new Dictionary<string, object?>(),
    });
});

Test("an inner scope wins over an outer one, and the call's own values win over both", () =>
{
    var log = new LogContext(Level.Information);
    using (BeginScope(log, "Step", "load"))
    {
        using (BeginScope(log, "Step", "save"))
        {
            Log(log, Level.Information, "Saving cart");
            Log(log, Level.Information, "Saving {Step}", "commit");
        }
        Log(log, Level.Information, "Back in {Phase}", "checkout");
    }
    Eq(log.Entries.Select(e => e.Properties).ToArray(), new object[]
    {
        new Dictionary<string, object?> { ["Step"] = "save" },
        new Dictionary<string, object?> { ["Step"] = "commit" },
        new Dictionary<string, object?> { ["Step"] = "load", ["Phase"] = "checkout" },
    });
});

Test("a template that does not match its arguments throws instead of logging a wrong line", () =>
{
    var log = new LogContext(Level.Information);
    Throws<ArgumentException>(() => Log(log, Level.Error, "Payment {PaymentId} failed for {UserId}", "p-1"));
    Throws<ArgumentException>(() => Log(log, Level.Error, "Payment {PaymentId} failed", "p-1", "u-7"));
    Eq(log.Entries.Count, 0);
});

