// ──────────────────────────── types ──────────────────────────────────────

enum Level { Trace, Debug, Information, Warning, Error, Critical }

record LogEntry(Level Level, string Template, string Message, IReadOnlyDictionary<string, object?> Properties);

/// <summary>Given: the minimum level, the sink and the scope stack of one logger.</summary>
sealed class LogContext(Level minimum)
{
    public Level Minimum { get; } = minimum;
    public List<LogEntry> Entries { get; } = new();
    public List<(string Name, object? Value)> Scopes { get; } = new();
}

/// <summary>Given: runs its action once, on the first Dispose.</summary>
sealed class Scope(Action onDispose) : IDisposable
{
    bool disposed;
    public void Dispose()
    {
        if (disposed) return;
        disposed = true;
        onDispose();
    }
}

drills.explanation:
Check the level first, walk the template once, then merge scopes before the call's own values:

```csharp
if (level < log.Minimum) return;
var (names, message) = Render(template, args);     // {{ is text, {Name:format} is a placeholder
var properties = new Dictionary<string, object?>();
foreach (var (name, value) in log.Scopes) properties[name] = value;
for (var i = 0; i < names.Count; i++) properties[names[i]] = args[i];
log.Entries.Add(new LogEntry(level, template, message, properties));
```

The template goes into the entry untouched: storing the rendered message in its place, which is what an interpolated string does, makes "the template is kept as written and each value becomes a named property" fail. Other wrong versions the tests catch: `<=` in the level check drops the line at the minimum itself, a `Scope` whose action does nothing leaks `CorrelationId` into "Request done", merging the scopes after the placeholder values lets the scope's `Step` overwrite `commit`, keeping `Amount:0.00` as the property name instead of `Amount`, and treating `{{id}}` as a placeholder instead of literal braces.

