drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  02 · log a request safely★★☆ core
//  concepts: allow-list headers · [Redacted] · secret query values · no bodies · no emails
// ─────────────────────────────────────────────────────────────────────────
//
//  Decide at the edge what may be written; everything else is marked, never copied.

using static Bootcamp.Check;
using System.Text.RegularExpressions;

IReadOnlyDictionary<string, object?> RequestLogFields(RequestInfo request)
{
    var allowed = new HashSet<string>(LogRules.AllowedHeaders, StringComparer.OrdinalIgnoreCase);
    var secret = new HashSet<string>(LogRules.SecretQueryKeys, StringComparer.OrdinalIgnoreCase);
    var headers = new Dictionary<string, string>();
    foreach (var (name, value) in request.Headers)
        headers[name] = allowed.Contains(name) ? value : LogRules.Redacted;
    var query = new Dictionary<string, string>();
    foreach (var (name, value) in request.Query)
        query[name] = secret.Contains(name) ? LogRules.Redacted : value;
    return new Dictionary<string, object?>
    {
        ["Method"] = request.Method,
        ["Path"] = Regex.Replace(request.Path, LogRules.EmailPattern, "[email]"),
        ["Query"] = query,
        ["Headers"] = headers,
        ["BodyLength"] = request.Body?.Length ?? 0,
    };
}

// Given: a typical sign-in call from a partner.
RequestInfo SignIn() => new(
