    new Dictionary<string, string>
    {
        ["Authorization"] = "Bearer eyJhbGciOi.payload.sig",
        ["Cookie"] = "session=9f2c41d0",
        ["Content-Type"] = "application/json",
        ["X-Correlation-Id"] = "c-91",
    },
    "{\"email\":\"ana@example.com\",\"password\":\"hunter2\"}");

